import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")

    if not data or not isinstance(data, list):
        raise ValueError("Invalid or empty data")

    processed_data = []
    for item in data:
        if not isinstance(item.get("Country"), str) or not isinstance(item.get("Population"), (int, float)):
            raise ValueError("Invalid data format")
        if item["Population"] < 0:
            raise ValueError("Population cannot be negative")
        processed_data.append({"Country": item["Country"], "Population": math.floor(item["Population"])})

    df = pd.DataFrame(processed_data, columns=["Country", "Population"])
    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Failed to write the file")

    return file_path, df

